window.__votdWeek && window.__votdWeek({"week":"2028-03-20","reading":"Jacob 1–4","days":[{"d":"2028-03-20","ref":"Jacob 1:9","b":"Jacob","c":1,"v":9,"he":"וְעַתָּה הֵחֵל נֶפִי לִזְקֹן וַיַּרְא כִּי קָרוֹב לָמוּת וְעַל־כֵּן מָשַׁח אִישׁ לִהְיוֹת מֶלֶךְ וּמוֹשֵׁל עַל־עַמּוֹ כְּפִי מַמְלְכוֹת הַמְּלָכִים׃","en":"Now Nephi began to be old, and he saw that he must soon die; wherefore, he anointed a man to be a king and a ruler over his people now, according to the reigns of the kings."},{"d":"2028-03-21","ref":"Jacob 1:10","b":"Jacob","c":1,"v":10,"he":"וַיֶּאֱהֲבוּ הָעָם אֶת־נֶפִי אַהֲבָה עַזָּה כִּי הָיָה מָגֵן גָּדוֹל לָהֶם וַיָּנֶף אֶת־חֶרֶב לָבָן לְהָגֵן עֲלֵיהֶם וַיַּעֲבֹד כׇּל־יָמָיו לְטוֹבָתָם׃","en":"The people having loved Nephi exceedingly, he having been a great protector for them, having wielded the sword of Laban in their defence, and having labored in all his days for their welfare—"},{"d":"2028-03-22","ref":"Jacob 2:18","b":"Jacob","c":2,"v":18,"he":"אַךְ לִפְנֵי בַקֶּשְׁכֶם עֹשֶׁר בַּקְּשׁוּ אֶת־מַלְכוּת אֱלֹהִים׃","en":"But before ye seek for riches, seek ye for the kingdom of God."},{"d":"2028-03-23","ref":"Jacob 2:24","b":"Jacob","c":2,"v":24,"he":"הִנֵּה דָוִד וּשְׁלֹמֹה אׇמְנָם הָיוּ לָהֶם נָשִׁים רַבּוֹת וּפִילַגְשִׁים אֲשֶׁר הָיָה תּוֹעֵבָה לְפָנַי נְאֻם־יְהוָה׃","en":"Behold, David and Solomon truly had many wives and concubines, which thing was abominable before me, saith the Lord."},{"d":"2028-03-24","ref":"Jacob 3:6","b":"Jacob","c":3,"v":6,"he":"וְעַתָּה שֹׁמְרִים הֵם אֶת־הַמִּצְוָה הַזֹּאת וּבַעֲבוּר שׇׁמְרָם אוֹתָהּ הַשְׁמֵד לֹא יַשְׁמִידֵם יְהוָה אֱלֹהִים כִּי יְרַחֵם עֲלֵיהֶם וּבְיוֹם אֶחָד יִהְיוּ לְעַם בָּרוּךְ׃","en":"And now, this commandment they observe to keep; wherefore, because of this observance, in keeping this commandment, the Lord God will not destroy them, but will be merciful unto them; and one day they shall become a blessed people."},{"d":"2028-03-25","ref":"Jacob 4:7","b":"Jacob","c":4,"v":7,"he":"אַךְ מַרְאֶה יְהוָה אֱלֹהִים לָנוּ חֻלְשָׁתֵנוּ לְמַעַן נֵדַע כִּי בְּחַסְדּוֹ וּבְרֹב עַנְוֹתָיו לִבְנֵי־הָאָדָם יֶשׁ־לָנוּ כֹּחַ לַעֲשׂוֹת אֶת־הַדְּבָרִים הָאֵלֶּה׃","en":"Nevertheless, the Lord God showeth us our weakness that we may know that it is by his grace, and his great condescensions unto the children of men, that we have power to do these things."},{"d":"2028-03-26","ref":"Jacob 4:10","b":"Jacob","c":4,"v":10,"he":"לָכֵן אַחַי אַל־תְּבַקְשׁוּ לְיַעֵץ אֶת־יְהוָה כִּי־אִם לְקַבֵּל עֵצָה מִיָּדוֹ כִּי הִנֵּה אַתֶּם יוֹדְעִים כִּי־הוּא יוֹעֵץ בְּחׇכְמָה וּבְצֶדֶק וּבְחֶסֶד גָּדוֹל עַל כׇּל מַעֲשָׂיו׃","en":"Wherefore, brethren, seek not to counsel the Lord, but to take counsel from his hand. For behold, ye yourselves know that he counseleth in wisdom, and in justice, and in great mercy, over all his works."}]});
